#import <Foundation/Foundation.h>
#import <UIKit/UIKit.h>

NSString* indentedDescription(UIView *view, int level) {
    NSString *indent = [@"" stringByPaddingToLength:level*2 withString:@" " startingAtIndex:0];
    NSString *viewDesc = [NSString stringWithFormat:@"%@%@ %@", 
                          indent, NSStringFromClass([view class]), NSStringFromCGRect(view.frame)];

    if ([view respondsToSelector:@selector(text)]) {
        NSString *text = [view performSelector:@selector(text)];
        if (text) viewDesc = [viewDesc stringByAppendingFormat:@" text:'%@'", text];
    }

    if ([view respondsToSelector:@selector(label)]) {
        NSString *label = [view performSelector:@selector(label)];
        if (label) viewDesc = [viewDesc stringByAppendingFormat:@" label:'%@'", label];
    }

    return viewDesc;
}

void exploreView(UIView *view, int maxLevel, int level) {
    if (level > maxLevel) return;

    NSLog(@"%@", indentedDescription(view, level));

    for (UIView *subview in view.subviews) {
        exploreView(subview, maxLevel, level + 1);
    }
}

